"""Idempotent local HTML integration, preserving native chat and camera implementation."""
from pathlib import Path
p=Path(__file__).with_name('dashboard.html');text=p.read_text(encoding='utf-8')
if 'id="arrangement"' not in text:
    style='''
.arrangement{padding:11px 14px;border-bottom:1px solid var(--line);background:#f6faf7}.plan-top{display:flex;justify-content:space-between;gap:10px;align-items:center}.plan-top strong{font-size:13px}#plan-reason{font-size:12px;line-height:1.6;margin:6px 0}#plan-stamp{font-size:10px;color:var(--muted)}#plan-next{font-size:11px;font-weight:600;margin-top:5px}.plan-steps{display:flex;gap:6px;overflow:auto;max-height:76px;margin-top:8px}.plan-step{min-width:120px;padding:7px 9px;border:1px solid var(--line);background:#fff;border-radius:7px}.plan-step strong{font-size:11px;display:block}.plan-step span{font-size:10px;color:var(--muted)}.plan-step.completed{background:#e6f4eb}.plan-step.running{border-color:var(--teal);background:#e7f3ef}.plan-step.failed{background:#ffebe7}.arrangement.stale{background:#fff8ec}.demo-controls{padding:9px 14px;border-bottom:1px solid var(--line)}.demo-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.demo-bar small{flex:1}.stop-btn{background:#b44e3b!important;color:#fff!important;border:0!important}.demo-content{padding-top:10px;max-height:220px;overflow:auto}.demo-row{display:flex;align-items:center;gap:7px;margin:8px 0;flex-wrap:wrap}.demo-row label{font-size:11px;min-width:62px}.demo-row select{border:1px solid var(--line);padding:5px;border-radius:5px;color:var(--ink);background:#fff}.demo-notice{font-size:11px;color:var(--teal);margin:6px 0;line-height:1.6}.demo-notice.error{color:#a24938}.demo-content p{font-size:11px;margin:5px 0;color:var(--muted)}button:disabled{opacity:.45;cursor:not-allowed}
'''
    text=text.replace('</style>',style+'</style>',1)
    fragment='''<section class="arrangement" id="arrangement" aria-label="Agent任务安排"><div class="plan-top"><strong id="plan-heading">Agnes 的任务安排</strong><small id="plan-stamp"></small></div><p id="plan-reason">等待 Agnes 安排。</p><div class="plan-steps" id="plan-steps"></div><div id="plan-next"></div></section>
<section class="demo-controls"><div class="demo-bar"><details id="demo-details"><summary>演示控制</summary></details><small id="demo-session">正在读取本轮聊天</small><button class="small-btn stop-btn" id="demo-stop" disabled>停止本轮</button></div><div class="demo-content" id="demo-content" hidden>
<div class="demo-row"><label>普通配送</label><select id="normal-first" aria-label="第一件目的站"><option value="station_a">A 护士站</option><option value="station_b">B 护士站</option><option value="station_c">C 护士站</option></select><select id="normal-second" aria-label="第二件目的站"><option value="station_c">C 护士站</option><option value="station_a">A 护士站</option><option value="station_b">B 护士站</option></select><button class="small-btn" id="demo-normal" disabled>发送配送任务</button></div>
<div class="demo-row"><label>追加急件</label><select id="urgent-station" aria-label="急件目的站"><option value="station_b">B 护士站</option><option value="station_a">A 护士站</option><option value="station_c">C 护士站</option></select><button class="small-btn" id="demo-urgent" disabled>追加急件</button></div>
<div class="demo-row"><label>接收异常</label><select id="receiver-station" aria-label="演示接收站"><option value="station_a">A 护士站</option><option value="station_b">B 护士站</option><option value="station_c">C 护士站</option></select><button class="small-btn" id="demo-pause" disabled>暂停接收</button><button class="small-btn" id="demo-resume" disabled>恢复接收</button></div>
<div class="demo-row"><button class="small-btn" id="demo-current">回到本轮聊天</button><button class="small-btn" id="demo-reset">新一轮</button><button class="small-btn" id="demo-retry">核验上次提交</button></div><p>按钮将短任务发给 Agnes；配送顺序由它决定。普通件 240、急件 100 仿真秒。接收异常是人为演示设置。</p><div id="demo-command-list"></div></div><p class="demo-notice" id="demo-notice" role="status"></p></section>
'''
    text=text.replace('<iframe id="chat"',fragment+'<iframe id="chat"',1)
    if 'id="arrangement"' not in text:raise RuntimeError('chat_entry_not_found')
    text=text.replace('latest=s;const good=', 'latest=s;window.renderArrangement?.(s);const good=',1)
    text=text.replace('新一轮先使用项目 reset 脚本，再创建新会话；不要从多个会话同时下单。','演示控制中的“新一轮”会保存当前结果并重建场景；每轮只由一个聊天控制。')
    text=text.replace('停止使用聊天中的 MHS Stop 操作，以“已确认静止”为准。','“停止本轮”会锁定本轮运动，以“已确认静止”为准。')
    text=text.replace('</script></html>','</script><script src="/workbench.js"></script><script>document.getElementById("demo-details").addEventListener("toggle",()=>document.getElementById("demo-content").hidden=!document.getElementById("demo-details").open);</script></html>')
    p.write_text(text,encoding='utf-8')
